// --- 1) Catálogo: o indicador mpe-compras-publicas (agenda inclusao) ---
// Cross-source PNCP × Receita Federal — ambos do data lake do Sebrae.
// Pequeno negócio = porte ME/EPP (MEI incluso). SEM threshold (sem faixa oficial).
const indicators = [
  {"_id": "mpe-compras-publicas", "label": "Participação dos pequenos negócios em compras públicas municipais (% do valor)", "referenceYear": "2025", "description": "Percentual do valor dos contratos públicos da esfera municipal (prefeitura, fundos e autarquias) firmados com fornecedores de pequeno porte (ME/EPP, incluindo MEI), no ano. Fonte cruzada: contratos do PNCP × porte do fornecedor na Receita Federal — ambos no data lake do Sebrae. O PNCP não publica o porte do fornecedor; ele vem da base da RF.", "source": "PNCP (Portal Nacional de Contratações Públicas, Lei 14.133/2021) × Receita Federal — ambos via data lake do Sebrae. Contratos da esfera municipal × porte do CNPJ na RF (RF_EMPRESAS), ano-alinhado. Pequeno negócio = porte ME/EPP (MEI incluso)", "sourceDataset": "sebrae_pncp_x_rfb_cnpj", "placements": [{"section": "agenda", "agendaId": "inclusao", "order": 6}]},
]
database.indicators.bulkWrite(indicators.map(i => ({ updateOne: {
  filter: { _id: i._id }, update: { $set: i }, upsert: true,
} })), { ordered: false })
print(`indicators(mpe-compras-publicas) -> ok (${indicators.length} docs)`)

